-- =====================================================================
-- doc-ai-platform 数据库基线 v3（企业级多租户文档处理平台）
--
-- 目标数据库：PostgreSQL 16+ / pgvector 0.8+ / pg_trgm
-- 设计基准：partner《修改.md》+《数据库表.md》+ v2 实现（sql/legacy/001_schema_v1.sql）
--
-- 【重要】本脚本是「重建脚本」，开头会 DROP 全部业务表。仅用于：
--   1) 全新环境初始化；2) 开发期重建（当前业务数据为空时）。
--   存量数据迁移请勿直接执行，见 docs/db-design-v3.md 第 8 节。
--
-- 【兼容性约定】v3 保留 v2 的全部列名与语义，只做「加法」：
--   - 新增列一律带 DEFAULT 或可空，已写好的 Java 代码（SysDept/SysUser/JWT 等）
--     无需改动即可在 v3 上运行；
--   - 主键改为 GENERATED BY DEFAULT AS IDENTITY（兼容 MyBatis-Plus IdType.AUTO
--     的 getGeneratedKeys，同时允许显式指定 id 用于数据迁移）。
--
-- 【设计约定】
--   1. 命名：snake_case；表名 sys_ 前缀仅用于平台级配置/审计表，业务域表不加前缀
--   2. 时间：一律 TIMESTAMPTZ NOT NULL DEFAULT now()，禁止无时区 TIMESTAMP
--   3. 布尔：布尔语义一律 BOOLEAN（禁止 SMALLINT 0/1）
--   4. 删除：实体表软删 deleted_at；关系表/日志表不做软删
--   5. 隔离：每张业务表携带 dept_id，并用「复合外键 (id, dept_id)」保证
--      引用不跨部门（数据库层兜底，不依赖 Service 自觉）
--   6. 状态：VARCHAR + CHECK 枚举（可读、易扩展，优于 PG ENUM 的改型成本）
--   7. 审计：created_at / updated_at 由触发器统一维护，业务代码不必手写
-- =====================================================================

-- ---------------------------------------------------------------------
-- 0. 扩展与通用函数
-- ---------------------------------------------------------------------
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS vector;
CREATE EXTENSION IF NOT EXISTS pg_trgm;   -- 中文子串检索（LIKE '%词%' 可走索引）

-- 统一维护 updated_at（业务代码只写业务字段）
CREATE OR REPLACE FUNCTION trg_touch_updated_at() RETURNS trigger AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- ---------------------------------------------------------------------
-- 1. 清理（重建脚本，顺序无关，CASCADE 处理依赖）
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS sys_audit_log        CASCADE;
DROP TABLE IF EXISTS task_log             CASCADE;
DROP TABLE IF EXISTS extract_result_history CASCADE;
DROP TABLE IF EXISTS extract_result       CASCADE;
DROP TABLE IF EXISTS task_document_rel    CASCADE;
DROP TABLE IF EXISTS task                 CASCADE;
DROP TABLE IF EXISTS template_field_mapping CASCADE;
DROP TABLE IF EXISTS extract_schema       CASCADE;
DROP TABLE IF EXISTS document_block       CASCADE;
DROP TABLE IF EXISTS document_version     CASCADE;
DROP TABLE IF EXISTS document_tag_rel     CASCADE;
DROP TABLE IF EXISTS email_inbox          CASCADE;
DROP TABLE IF EXISTS document             CASCADE;
DROP TABLE IF EXISTS sys_tag              CASCADE;
DROP TABLE IF EXISTS email_whitelist      CASCADE;
DROP TABLE IF EXISTS dept_email_config    CASCADE;
DROP TABLE IF EXISTS sys_user             CASCADE;
DROP TABLE IF EXISTS sys_dept             CASCADE;

-- =====================================================================
-- 2. 组织架构与权限
-- =====================================================================

-- 2.1 部门（租户）。数据隔离边界，支持树形层级。
CREATE TABLE sys_dept (
    id          BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    parent_id   BIGINT      REFERENCES sys_dept(id) ON DELETE RESTRICT,
                            -- 根部门为 NULL。v2 用 0 作哨兵，由触发器自动归一为 NULL（见末尾）
    dept_code   VARCHAR(32),                 -- 部门编码，对外集成/报表用，可空
    name        VARCHAR(64) NOT NULL,
    sort_no     INT         NOT NULL DEFAULT 0,
    status      VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at  TIMESTAMPTZ,
    CONSTRAINT ck_dept_status CHECK (status IN ('ACTIVE', 'DISABLED')),
    CONSTRAINT ck_dept_not_self CHECK (parent_id IS NULL OR parent_id <> id)
);
-- 同层不重名（NULLS NOT DISTINCT：根部门之间也要互斥）
CREATE UNIQUE INDEX uq_dept_parent_name ON sys_dept (parent_id, name)
    NULLS NOT DISTINCT WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX uq_dept_code ON sys_dept (dept_code)
    WHERE deleted_at IS NULL AND dept_code IS NOT NULL;

COMMENT ON TABLE  sys_dept IS '部门（租户），数据隔离边界';
COMMENT ON COLUMN sys_dept.parent_id IS '上级部门；NULL 表示根部门';
COMMENT ON COLUMN sys_dept.dept_code IS '部门编码，可选，用于外部系统对接';

-- 2.2 用户。一个账号归属一个部门（多部门场景见 docs 第 9 节演进路径）。
CREATE TABLE sys_user (
    id             BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    dept_id        BIGINT      NOT NULL REFERENCES sys_dept(id) ON DELETE RESTRICT,
    username       VARCHAR(64) NOT NULL,
    password_hash  VARCHAR(255) NOT NULL,       -- BCrypt，含算法前缀与 cost
    real_name      VARCHAR(64),
    email          VARCHAR(128),
    phone          VARCHAR(32),
    role           VARCHAR(32) NOT NULL,        -- ADMIN / DISPATCHER / PROCESSOR
    status         VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',
    last_login_at  TIMESTAMPTZ,
    password_updated_at TIMESTAMPTZ,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at     TIMESTAMPTZ,
    CONSTRAINT ck_user_role   CHECK (role IN ('ADMIN', 'DISPATCHER', 'PROCESSOR')),
    CONSTRAINT ck_user_status CHECK (status IN ('ACTIVE', 'DISABLED', 'LOCKED'))
);
-- 登录名全局唯一（登录时无需先选租户）；软删后释放，允许重建同名账号
CREATE UNIQUE INDEX uq_user_username ON sys_user (username) WHERE deleted_at IS NULL;
CREATE INDEX idx_user_dept_role ON sys_user (dept_id, role) WHERE deleted_at IS NULL;
-- 复合唯一键：供其他表建立「同部门」复合外键
ALTER TABLE sys_user ADD CONSTRAINT uq_user_id_dept UNIQUE (id, dept_id);

COMMENT ON TABLE  sys_user IS '系统用户（管理员/分配员/处理员）';
COMMENT ON COLUMN sys_user.password_hash IS 'BCrypt 摘要，禁止明文或可逆加密';

-- 2.3 部门邮箱配置（IMAP）。授权码必须密文存储。
CREATE TABLE dept_email_config (
    id              BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    dept_id         BIGINT      NOT NULL REFERENCES sys_dept(id) ON DELETE CASCADE,
    email_address   VARCHAR(128) NOT NULL,
    imap_host       VARCHAR(128) NOT NULL,
    imap_port       SMALLINT    NOT NULL DEFAULT 993,
    use_ssl         BOOLEAN     NOT NULL DEFAULT TRUE,
    folder          VARCHAR(64) NOT NULL DEFAULT 'INBOX',
    auth_code_enc   TEXT        NOT NULL,       -- 密文（AES-GCM/KMS 信封），禁止明文
    auth_code_kid   VARCHAR(64),                -- 密钥版本，支持轮换
    last_uid        BIGINT      NOT NULL DEFAULT 0,  -- IMAP 增量位点
    last_check_at   TIMESTAMPTZ,
    last_error      TEXT,
    enabled         BOOLEAN     NOT NULL DEFAULT TRUE,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at      TIMESTAMPTZ,
    CONSTRAINT ck_email_port CHECK (imap_port BETWEEN 1 AND 65535)
);
-- 邮箱地址大小写不敏感去重
CREATE UNIQUE INDEX uq_email_cfg_addr ON dept_email_config (dept_id, lower(email_address))
    WHERE deleted_at IS NULL;
CREATE INDEX idx_email_cfg_enabled ON dept_email_config (enabled) WHERE deleted_at IS NULL;

COMMENT ON COLUMN dept_email_config.auth_code_enc IS 'IMAP 授权码密文，应用侧解密，接口只写不读';

-- 2.4 发件人白名单（邮件入库前置过滤）。
CREATE TABLE email_whitelist (
    id          BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    dept_id     BIGINT      NOT NULL REFERENCES sys_dept(id) ON DELETE CASCADE,
    match_type  VARCHAR(16) NOT NULL DEFAULT 'DOMAIN',  -- DOMAIN / ADDRESS / SUFFIX
    pattern     VARCHAR(255) NOT NULL,                  -- 如 supplier.com / *@abc.cn
    remark      VARCHAR(255),
    enabled     BOOLEAN     NOT NULL DEFAULT TRUE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_wl_type CHECK (match_type IN ('DOMAIN', 'ADDRESS', 'SUFFIX'))
);
CREATE UNIQUE INDEX uq_wl_pattern ON email_whitelist (dept_id, match_type, lower(pattern));

-- =====================================================================
-- 3. 资产库：标签、文件、版本
-- =====================================================================

-- 3.1 部门标签库
CREATE TABLE sys_tag (
    id          BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    dept_id     BIGINT      NOT NULL REFERENCES sys_dept(id) ON DELETE CASCADE,
    tag_name    VARCHAR(64) NOT NULL,
    color       VARCHAR(16),
    sort_no     INT         NOT NULL DEFAULT 0,
    created_by  BIGINT,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at  TIMESTAMPTZ
);
CREATE UNIQUE INDEX uq_tag_name ON sys_tag (dept_id, lower(tag_name))
    WHERE deleted_at IS NULL;
-- 复合唯一键：供关系表建立「同部门」复合外键
ALTER TABLE sys_tag ADD CONSTRAINT uq_tag_id_dept UNIQUE (id, dept_id);

-- 3.2 文件元数据（源文件 / 模板 / 产出统一管理）
--   说明：不做 (dept_id, sha256) 唯一约束。理由见 docs 第 4.1 节：
--   ① 同一合同重复提交是正常业务；② 唯一键会与软删冲突（删后无法重传）。
--   幂等性由 email_inbox 的唯一键 + 应用层查重提示共同保证。
CREATE TABLE document (
    id             BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    dept_id        BIGINT      NOT NULL REFERENCES sys_dept(id) ON DELETE RESTRICT,
    uploader_id    BIGINT,                       -- 系统/邮件入库时为 NULL
    uploader_type  VARCHAR(16) NOT NULL DEFAULT 'USER',  -- USER / SYSTEM / EMAIL
    file_name      VARCHAR(255) NOT NULL,
    file_type      VARCHAR(32) NOT NULL,         -- docx / xlsx / md / txt / pdf（统一小写，与扩展名一致）
    mime_type      VARCHAR(128),
    file_category  VARCHAR(16) NOT NULL,         -- SOURCE / TEMPLATE / OUTPUT
    file_size      BIGINT      NOT NULL,
    sha256         CHAR(64)    NOT NULL,
    storage_bucket VARCHAR(64) NOT NULL DEFAULT 'docai',
    storage_key    VARCHAR(512) NOT NULL,
    source_type    VARCHAR(16) NOT NULL DEFAULT 'WEB',   -- WEB / EMAIL / API
    source_ref     VARCHAR(255),                 -- 邮件 message-id 等外部溯源标识
    is_shared      BOOLEAN     NOT NULL DEFAULT FALSE,   -- 全部门可见（共有资产：规范手册等）
    parse_status   VARCHAR(16) NOT NULL DEFAULT 'UPLOADED',
    parse_error    TEXT,
    parse_attempts SMALLINT    NOT NULL DEFAULT 0,
    parsed_at      TIMESTAMPTZ,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at     TIMESTAMPTZ,
    CONSTRAINT ck_doc_category CHECK (file_category IN ('SOURCE', 'TEMPLATE', 'OUTPUT')),
    CONSTRAINT ck_doc_status   CHECK (parse_status IN ('UPLOADED', 'PARSING', 'PARSED', 'FAILED', 'SKIPPED')),
    CONSTRAINT ck_doc_source   CHECK (source_type IN ('WEB', 'EMAIL', 'API')),
    CONSTRAINT ck_doc_size     CHECK (file_size >= 0),
    CONSTRAINT ck_doc_sha      CHECK (sha256 ~ '^[0-9a-f]{64}$'),
    -- 上传人必须属于本部门；系统/邮件入库时 uploader_id 为 NULL（MATCH SIMPLE 不校验）
    CONSTRAINT fk_doc_uploader FOREIGN KEY (uploader_id, dept_id)
        REFERENCES sys_user (id, dept_id) ON DELETE RESTRICT
);
-- 复合唯一键：供下游表建立「同部门」复合外键
ALTER TABLE document ADD CONSTRAINT uq_document_id_dept UNIQUE (id, dept_id);
-- 文件池列表页：部门 + 分类 + 时间倒序（覆盖排序，避免 Sort 节点）
CREATE INDEX idx_doc_dept_cat_time ON document (dept_id, file_category, created_at DESC)
    WHERE deleted_at IS NULL;
-- 解析队列：只扫待处理文件
CREATE INDEX idx_doc_parse_pending ON document (parse_status) 
    WHERE deleted_at IS NULL AND parse_status IN ('UPLOADED', 'FAILED');
-- 查重提示（非唯一，允许重复但可秒级发现）
CREATE INDEX idx_doc_sha ON document (dept_id, sha256) WHERE deleted_at IS NULL;
-- 共享资产
CREATE INDEX idx_doc_shared ON document (is_shared) WHERE is_shared AND deleted_at IS NULL;

COMMENT ON COLUMN document.is_shared     IS 'TRUE=全部门可见的共有资产（规范手册等）';
COMMENT ON COLUMN document.parse_status  IS '解析状态，与业务状态无关；可重试，parse_attempts 计数';

-- 3.3 文件-标签关联
CREATE TABLE document_tag_rel (
    document_id BIGINT      NOT NULL,
    tag_id      BIGINT      NOT NULL,
    dept_id     BIGINT      NOT NULL,
    created_by  BIGINT,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (document_id, tag_id),
    CONSTRAINT fk_dtr_doc FOREIGN KEY (document_id, dept_id)
        REFERENCES document (id, dept_id) ON DELETE CASCADE,
    CONSTRAINT fk_dtr_tag FOREIGN KEY (tag_id, dept_id)
        REFERENCES sys_tag (id, dept_id) ON DELETE CASCADE
);
-- 按标签筛选文件（文件池最核心的查询路径）
CREATE INDEX idx_dtr_tag_doc ON document_tag_rel (tag_id, document_id);
CREATE INDEX idx_dtr_dept ON document_tag_rel (dept_id, tag_id, document_id);

-- 3.4 文件版本（文档智能操作模块：预览→应用→回滚）
CREATE TABLE document_version (
    id          BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    document_id BIGINT      NOT NULL REFERENCES document(id) ON DELETE CASCADE,
    dept_id     BIGINT      NOT NULL REFERENCES sys_dept(id) ON DELETE RESTRICT,
    version_no  INT         NOT NULL,
    storage_key VARCHAR(512) NOT NULL,
    file_size   BIGINT      NOT NULL,
    sha256      CHAR(64)    NOT NULL,
    change_note VARCHAR(255),
    created_by  BIGINT,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_ver_no CHECK (version_no > 0)
);
CREATE UNIQUE INDEX uq_ver_doc_no ON document_version (document_id, version_no);
CREATE INDEX idx_ver_dept_time ON document_version (dept_id, created_at DESC);

-- =====================================================================
-- 4. 邮件接入：待确认队列
-- =====================================================================
CREATE TABLE email_inbox (
    id               BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    dept_id          BIGINT      NOT NULL REFERENCES sys_dept(id) ON DELETE CASCADE,
    config_id        BIGINT      NOT NULL REFERENCES dept_email_config(id) ON DELETE CASCADE,
    message_uid      BIGINT      NOT NULL,        -- IMAP UID
    attachment_index SMALLINT    NOT NULL DEFAULT 0,
    from_addr        VARCHAR(255) NOT NULL,
    subject          VARCHAR(512),
    received_at      TIMESTAMPTZ,
    attachment_name  VARCHAR(255) NOT NULL,
    file_size        BIGINT      NOT NULL,
    sha256           CHAR(64)    NOT NULL,
    storage_key      VARCHAR(512) NOT NULL,
    status           VARCHAR(16) NOT NULL DEFAULT 'PENDING',  -- PENDING / CLAIMED / REJECTED
    document_id      BIGINT,                      -- 认领后关联的 document
    reject_reason    VARCHAR(255),
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_inbox_status CHECK (status IN ('PENDING', 'CLAIMED', 'REJECTED')),
    CONSTRAINT fk_inbox_doc FOREIGN KEY (document_id, dept_id)
        REFERENCES document (id, dept_id) ON DELETE RESTRICT
);
-- 拉取幂等：同一 UID 的同一附件只入队一次
CREATE UNIQUE INDEX uq_inbox_uid ON email_inbox (config_id, message_uid, attachment_index);
-- 待确认列表
CREATE INDEX idx_inbox_pending ON email_inbox (dept_id, status, created_at DESC)
    WHERE status = 'PENDING';

COMMENT ON TABLE email_inbox IS '邮件附件待确认队列：自动拉取→白名单过滤→分配员认领入库';

-- =====================================================================
-- 5. 文档解析与向量（RAG 基础）
-- =====================================================================
CREATE TABLE document_block (
    id              BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    dept_id         BIGINT      NOT NULL,        -- 冗余：向量检索必须先按租户过滤
    document_id     BIGINT      NOT NULL,
    block_index     INT         NOT NULL,
    block_type      VARCHAR(16) NOT NULL,        -- TITLE / PARAGRAPH / TABLE / IMAGE
    content         TEXT        NOT NULL,
    table_json      JSONB,
    heading_path    VARCHAR(512),
    cell_ref        VARCHAR(128),
    page_no         INT,
    char_len        INT         NOT NULL DEFAULT 0,
    token_count     INT,                         -- 供 LLM 上下文预算
    embedding       vector(1536),
    embedding_model VARCHAR(64),                 -- 如 text-embedding-v3
    embedding_dim   SMALLINT,
    embedded_at     TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT fk_block_doc FOREIGN KEY (document_id, dept_id)
        REFERENCES document (id, dept_id) ON DELETE CASCADE,
    CONSTRAINT ck_block_type CHECK (block_type IN ('TITLE', 'PARAGRAPH', 'TABLE', 'IMAGE')),
    CONSTRAINT ck_block_idx  CHECK (block_index >= 0)
);
-- 同一文档的块序号唯一：重试解析不会产生重复块
CREATE UNIQUE INDEX uq_block_doc_idx ON document_block (document_id, block_index);
-- 按租户 + 文档取块（复核页双屏对照、证据回查）
CREATE INDEX idx_block_dept_doc ON document_block (dept_id, document_id, block_index);
-- HNSW 余弦索引。生产环境建议按租户分区或使用 pgvector 迭代扫描，
-- 避免「先跨租户召回再过滤」导致召回率下降（见 docs 第 5.2 节）
CREATE INDEX idx_block_embedding ON document_block
    USING hnsw (embedding vector_cosine_ops) WITH (m = 16, ef_construction = 64);
-- 中文子串检索：LIKE '%关键词%' 走 trigram 索引，避免全表扫描
CREATE INDEX idx_block_content_trgm ON document_block USING gin (content gin_trgm_ops);

COMMENT ON COLUMN document_block.dept_id IS '冗余租户列：向量检索必须带此条件，否则存在跨租户召回风险';
COMMENT ON COLUMN document_block.embedding_model IS '生成该向量的模型标识；换模型后据此圈定待重算数据';

-- =====================================================================
-- 6. 抽取 Schema 与模板映射
-- =====================================================================
CREATE TABLE extract_schema (
    id            BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    dept_id       BIGINT      NOT NULL REFERENCES sys_dept(id) ON DELETE RESTRICT,
    creator_id    BIGINT,
    name          VARCHAR(128) NOT NULL,
    prompt_text   TEXT,                          -- 分配员的自然语言原始描述
    schema_json   JSONB       NOT NULL,          -- LLM 生成的字段定义
    version       INT         NOT NULL DEFAULT 1,
    status        VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',  -- DRAFT / ACTIVE / ARCHIVED
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at    TIMESTAMPTZ,
    CONSTRAINT ck_schema_status CHECK (status IN ('DRAFT', 'ACTIVE', 'ARCHIVED')),
    CONSTRAINT ck_schema_json   CHECK (jsonb_typeof(schema_json) = 'object'),
    CONSTRAINT fk_schema_creator FOREIGN KEY (creator_id, dept_id)
        REFERENCES sys_user (id, dept_id) ON DELETE RESTRICT
);
ALTER TABLE extract_schema ADD CONSTRAINT uq_schema_id_dept UNIQUE (id, dept_id);
CREATE UNIQUE INDEX uq_schema_name_ver ON extract_schema (dept_id, name, version)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_schema_dept ON extract_schema (dept_id, status) WHERE deleted_at IS NULL;

COMMENT ON COLUMN extract_schema.schema_json IS
  '{"fields":[{"key":"amount","label":"金额","type":"number","unit":"万元","required":true,"description":"合同总金额"}]}';

-- 6.2 模板字段映射：回填的「地基」。没有它就无法把 field_key 定位到书签/单元格。
CREATE TABLE template_field_mapping (
    id             BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    dept_id        BIGINT      NOT NULL REFERENCES sys_dept(id) ON DELETE RESTRICT,
    template_doc_id BIGINT     NOT NULL,
    schema_id      BIGINT,
    field_key      VARCHAR(64) NOT NULL,
    anchor_type    VARCHAR(16) NOT NULL,        -- BOOKMARK / CELL / PLACEHOLDER
    anchor_ref     VARCHAR(128) NOT NULL,       -- 书签名 / 单元格地址 / 占位符
    sheet_name     VARCHAR(64),                 -- Excel 专用
    value_type     VARCHAR(16) NOT NULL DEFAULT 'TEXT',
    value_format   VARCHAR(64),                 -- 如 yyyy-MM-dd / #,##0.00
    unit           VARCHAR(16),
    is_required    BOOLEAN     NOT NULL DEFAULT FALSE,
    ordinal        INT         NOT NULL DEFAULT 0,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT fk_tfm_doc FOREIGN KEY (template_doc_id, dept_id)
        REFERENCES document (id, dept_id) ON DELETE CASCADE,
    CONSTRAINT fk_tfm_schema FOREIGN KEY (schema_id, dept_id)
        REFERENCES extract_schema (id, dept_id) ON DELETE RESTRICT,
    CONSTRAINT ck_tfm_anchor CHECK (anchor_type IN ('BOOKMARK', 'CELL', 'PLACEHOLDER')),
    CONSTRAINT ck_tfm_type   CHECK (value_type IN ('TEXT', 'NUMBER', 'DATE', 'BOOLEAN', 'ENUM'))
);
CREATE UNIQUE INDEX uq_tfm_field ON template_field_mapping (template_doc_id, field_key);
-- 一个锚点只能被一个字段占用，防止回填时互相覆盖
CREATE UNIQUE INDEX uq_tfm_anchor ON template_field_mapping
    (template_doc_id, anchor_type, COALESCE(sheet_name, ''), anchor_ref);

COMMENT ON TABLE template_field_mapping IS '模板字段映射：field_key → Word 书签 / Excel 单元格';

-- =====================================================================
-- 7. 任务流转
-- =====================================================================
CREATE TABLE task (
    id              BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    dept_id         BIGINT      NOT NULL REFERENCES sys_dept(id) ON DELETE RESTRICT,
    creator_id      BIGINT,
    assignee_id     BIGINT,
    task_type       VARCHAR(16) NOT NULL,        -- EXTRACT / FILL
    schema_id       BIGINT,
    template_doc_id BIGINT,
    schema_snapshot JSONB,                       -- 建单时的 Schema 快照，保证可复现
    status          VARCHAR(16) NOT NULL DEFAULT 'PENDING',
    progress        SMALLINT    NOT NULL DEFAULT 0,
    priority        SMALLINT    NOT NULL DEFAULT 5,   -- 1 最高，9 最低
    payload_json    JSONB,                       -- 任务入参快照（字段范围等）
    result_json     JSONB,                       -- 执行结果摘要
    result_doc_id   BIGINT,
    error_msg       TEXT,
    attempt_count   SMALLINT    NOT NULL DEFAULT 0,
    claimed_at      TIMESTAMPTZ,                 -- 认领时间（并发控制）
    lease_expires_at TIMESTAMPTZ,                -- 租约到期，超时可被重新认领
    started_at      TIMESTAMPTZ,
    completed_at    TIMESTAMPTZ,
    version_no      INT         NOT NULL DEFAULT 0,  -- 乐观锁
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at      TIMESTAMPTZ,
    CONSTRAINT ck_task_type   CHECK (task_type IN ('EXTRACT', 'FILL')),
    CONSTRAINT ck_task_status CHECK (status IN
        ('PENDING', 'ASSIGNED', 'PROCESSING', 'COMPLETED', 'FAILED', 'CANCELLED')),
    CONSTRAINT ck_task_progress CHECK (progress BETWEEN 0 AND 100),
    CONSTRAINT ck_task_priority CHECK (priority BETWEEN 1 AND 9),
    CONSTRAINT ck_task_time CHECK (completed_at IS NULL OR completed_at >= created_at),
    CONSTRAINT fk_task_creator  FOREIGN KEY (creator_id, dept_id)
        REFERENCES sys_user (id, dept_id) ON DELETE RESTRICT,
    CONSTRAINT fk_task_assignee FOREIGN KEY (assignee_id, dept_id)
        REFERENCES sys_user (id, dept_id) ON DELETE RESTRICT,
    CONSTRAINT fk_task_schema   FOREIGN KEY (schema_id, dept_id)
        REFERENCES extract_schema (id, dept_id) ON DELETE RESTRICT,
    CONSTRAINT fk_task_tpl      FOREIGN KEY (template_doc_id, dept_id)
        REFERENCES document (id, dept_id) ON DELETE RESTRICT,
    CONSTRAINT fk_task_result   FOREIGN KEY (result_doc_id, dept_id)
        REFERENCES document (id, dept_id) ON DELETE RESTRICT
);
ALTER TABLE task ADD CONSTRAINT uq_task_id_dept UNIQUE (id, dept_id);
-- 任务列表 / 看板：部门 + 状态 + 时间
CREATE INDEX idx_task_dept_status ON task (dept_id, status, created_at DESC)
    WHERE deleted_at IS NULL;
-- 自动分配引擎：按处理员统计积压（覆盖 GROUP BY assignee_id）
CREATE INDEX idx_task_dept_assignee ON task (dept_id, assignee_id, status)
    WHERE deleted_at IS NULL;
-- 待派发/待认领轮询：部分索引只含热数据，体积极小
CREATE INDEX idx_task_pending ON task (dept_id, priority, created_at)
    WHERE status = 'PENDING' AND deleted_at IS NULL;
-- 超时租约回收
CREATE INDEX idx_task_lease ON task (lease_expires_at) 
    WHERE status = 'PROCESSING' AND lease_expires_at IS NOT NULL;

COMMENT ON COLUMN task.version_no IS '乐观锁版本号，更新时 WHERE version_no = ?';
COMMENT ON COLUMN task.lease_expires_at IS '处理租约；超时未续约可由其他处理员重新认领';

-- 7.2 任务包含的源文件
CREATE TABLE task_document_rel (
    task_id     BIGINT      NOT NULL,
    document_id BIGINT      NOT NULL,
    dept_id     BIGINT      NOT NULL,
    ord         INT         NOT NULL DEFAULT 0,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (task_id, document_id),
    CONSTRAINT fk_tdr_task FOREIGN KEY (task_id, dept_id)
        REFERENCES task (id, dept_id) ON DELETE CASCADE,
    CONSTRAINT fk_tdr_doc FOREIGN KEY (document_id, dept_id)
        REFERENCES document (id, dept_id) ON DELETE CASCADE
);
CREATE INDEX idx_tdr_doc ON task_document_rel (document_id, task_id);

-- =====================================================================
-- 8. 抽取结果与审计
-- =====================================================================

-- 8.1 字段级结果。采用「多候选 + 单选终稿」模型：
--     一个任务的多份文档可能都提供了同一字段（如 3 份报价单的"总价"），
--     全部保留为候选，由人工/规则标记 is_selected 的终稿。
CREATE TABLE extract_result (
    id               BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    dept_id          BIGINT      NOT NULL,
    task_id          BIGINT      NOT NULL,
    document_id      BIGINT      NOT NULL,
    field_key        VARCHAR(64) NOT NULL,
    value_type       VARCHAR(16) NOT NULL DEFAULT 'TEXT',
    field_value      TEXT,                       -- 展示用原文（含单位）
    value_num        NUMERIC(20,4),               -- 归一化数值，供聚合/排序
    value_date       DATE,
    value_bool       BOOLEAN,
    value_unit       VARCHAR(16),
    raw_value        TEXT,                       -- 模型原始输出
    confidence       NUMERIC(5,4),
    evidence_block_id BIGINT,
    evidence_text    TEXT,                       -- 证据快照：块被清理后仍可追溯
    is_selected      BOOLEAN     NOT NULL DEFAULT FALSE,  -- 是否为该字段终稿
    is_modified      BOOLEAN     NOT NULL DEFAULT FALSE,  -- 处理员是否改过
    is_verified      BOOLEAN     NOT NULL DEFAULT FALSE,  -- 是否人工确认
    modified_by      BIGINT,
    modified_at      TIMESTAMPTZ,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT fk_res_task FOREIGN KEY (task_id, dept_id)
        REFERENCES task (id, dept_id) ON DELETE CASCADE,
    CONSTRAINT fk_res_doc FOREIGN KEY (document_id, dept_id)
        REFERENCES document (id, dept_id) ON DELETE RESTRICT,
    CONSTRAINT fk_res_block FOREIGN KEY (evidence_block_id)
        REFERENCES document_block (id) ON DELETE SET NULL,
    CONSTRAINT ck_res_conf  CHECK (confidence IS NULL OR (confidence >= 0 AND confidence <= 1)),
    CONSTRAINT ck_res_type  CHECK (value_type IN ('TEXT', 'NUMBER', 'DATE', 'BOOLEAN', 'ENUM')),
    CONSTRAINT ck_res_num   CHECK (value_type <> 'NUMBER' OR field_value IS NULL OR value_num IS NOT NULL)
);
-- 同一任务+文档+字段唯一：重跑抽取走 UPSERT，不产生重复行
CREATE UNIQUE INDEX uq_res_candidate ON extract_result (task_id, document_id, field_key);
-- 每个字段最多一个终稿
CREATE UNIQUE INDEX uq_res_selected ON extract_result (task_id, field_key) WHERE is_selected;
-- 复核页按任务聚合加载
CREATE INDEX idx_res_task ON extract_result (task_id, field_key);
-- 低置信度待复核清单
CREATE INDEX idx_res_low_conf ON extract_result (dept_id, confidence)
    WHERE NOT is_verified;

COMMENT ON COLUMN extract_result.is_selected IS '该字段的终稿标记，每 task_id+field_key 至多一条';

-- 8.2 修正留痕：AI 原值 → 人工终值的完整轨迹（支撑准确率统计与追责）
CREATE TABLE extract_result_history (
    id           BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    result_id    BIGINT      NOT NULL REFERENCES extract_result(id) ON DELETE CASCADE,
    task_id      BIGINT      NOT NULL,
    field_key    VARCHAR(64) NOT NULL,
    old_value    TEXT,
    new_value    TEXT,
    old_confidence NUMERIC(5,4),
    operator_id  BIGINT,
    reason       VARCHAR(255),
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_res_hist ON extract_result_history (result_id, created_at);
CREATE INDEX idx_res_hist_task ON extract_result_history (task_id, created_at);

-- 8.3 任务操作日志（append-only，不随业务表级联删除）
CREATE TABLE task_log (
    id          BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    dept_id     BIGINT      NOT NULL,
    task_id     BIGINT      NOT NULL,
    operator_id BIGINT,
    action      VARCHAR(64) NOT NULL,      -- CREATE / ASSIGN / CLAIM / EXTRACT / COMPLETE / FAIL / REASSIGN
    from_status VARCHAR(16),
    to_status   VARCHAR(16),
    detail      JSONB,
    ip_addr     INET,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_task_log_task ON task_log (task_id, created_at DESC);
CREATE INDEX idx_task_log_dept ON task_log (dept_id, created_at DESC);

COMMENT ON TABLE task_log IS '任务状态流转审计，append-only：禁止 UPDATE/DELETE';

-- 8.4 通用审计日志（认证、配置变更、删除等高危操作）
CREATE TABLE sys_audit_log (
    id          BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    dept_id     BIGINT,
    user_id     BIGINT,
    action      VARCHAR(64) NOT NULL,      -- LOGIN / LOGIN_FAIL / USER_CREATE / DOC_DELETE / CFG_UPDATE ...
    target_type VARCHAR(32),
    target_id   BIGINT,
    detail      JSONB,
    ip_addr     INET,
    user_agent  VARCHAR(255),
    success     BOOLEAN     NOT NULL DEFAULT TRUE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_audit_dept_time ON sys_audit_log (dept_id, created_at DESC);
CREATE INDEX idx_audit_user_time ON sys_audit_log (user_id, created_at DESC);
CREATE INDEX idx_audit_action ON sys_audit_log (action, created_at DESC);

COMMENT ON TABLE sys_audit_log IS '通用审计日志，append-only，按保留期归档';

-- =====================================================================
-- 9. 兼容层：v2 用 0 表示根部门，v3 规范为 NULL
--    触发器自动归一，保证已写好的 Java 代码（parentId=0L）无需改动。
-- =====================================================================
CREATE OR REPLACE FUNCTION trg_dept_parent_zero_to_null() RETURNS trigger AS $$
BEGIN
    IF NEW.parent_id = 0 THEN
        NEW.parent_id := NULL;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_dept_parent_norm ON sys_dept;
CREATE TRIGGER trg_dept_parent_norm BEFORE INSERT OR UPDATE ON sys_dept
    FOR EACH ROW EXECUTE FUNCTION trg_dept_parent_zero_to_null();

-- =====================================================================
-- 10. updated_at 自动维护
-- =====================================================================
DO $$
DECLARE t text;
BEGIN
    FOREACH t IN ARRAY ARRAY[
        'sys_dept', 'sys_user', 'dept_email_config', 'email_whitelist', 'sys_tag',
        'document', 'email_inbox', 'extract_schema', 'template_field_mapping',
        'task', 'extract_result'
    ] LOOP
        EXECUTE format('DROP TRIGGER IF EXISTS trg_touch_%1$s ON %1$s', t);
        EXECUTE format(
            'CREATE TRIGGER trg_touch_%1$s BEFORE UPDATE ON %1$s
             FOR EACH ROW EXECUTE FUNCTION trg_touch_updated_at()', t);
    END LOOP;
END $$;

-- =====================================================================
-- 11. 自治愈：同层部门重名（含根部门）—— 由 uq_dept_parent_name 保证
-- =====================================================================
-- 说明：NULLS NOT DISTINCT 需 PostgreSQL 15+，本项目锁定 PG16，可用。
